package com.example.inventoryapp;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.Manifest;import android.telephony.SmsManager;import android.text.InputType;import android.widget.*;
public class InventoryActivity extends Activity{
 private InventoryDatabase db;private long owner;private TableLayout grid;private EditText name,qty;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_inventory);db=new InventoryDatabase(this);owner=getSharedPreferences("session",0).getLong("id",-1);if(owner<0){startActivity(new Intent(this,MainActivity.class));finish();return;}grid=findViewById(R.id.inventoryGrid);name=findViewById(R.id.itemNameText);qty=findViewById(R.id.itemQuantityText);findViewById(R.id.buttonAddItem).setOnClickListener(v->add());findViewById(R.id.buttonNotificationSettings).setOnClickListener(v->startActivity(new Intent(this,SmsPermissionActivity.class)));refresh();}
 private void message(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void add(){String n=name.getText().toString().trim();int q;try{q=Integer.parseInt(qty.getText().toString());}catch(Exception e){message("Enter a valid quantity");return;}if(n.isEmpty()||q<0){message("Item name and nonnegative quantity required");return;}if(db.add(owner,n,q)<0){message("Save failed");return;}name.setText("");qty.setText("");refresh();if(q==0)alert(n);}
 private void refresh(){while(grid.getChildCount()>1)grid.removeViewAt(1);for(InventoryDatabase.Item item:db.all(owner)){TableRow row=new TableRow(this);TextView n=new TextView(this);n.setText(item.name);n.setPadding(4,8,4,8);TextView q=new TextView(this);q.setText(""+item.quantity);q.setPadding(4,8,4,8);Button edit=new Button(this);edit.setText("EDIT");edit.setOnClickListener(v->edit(item));Button del=new Button(this);del.setText("DELETE");del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Delete "+item.name+"?").setPositiveButton("Delete",(d,w)->{db.delete(owner,item.id);refresh();}).setNegativeButton("Cancel",null).show());row.addView(n);row.addView(q);row.addView(edit);row.addView(del);grid.addView(row);}}
 private void edit(InventoryDatabase.Item item){EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setText(""+item.quantity);new AlertDialog.Builder(this).setTitle("Quantity for "+item.name).setView(input).setPositiveButton("Save",(d,w)->{try{int updated=Integer.parseInt(input.getText().toString());if(updated<0){message("Quantity must be nonnegative");return;}db.update(owner,item.id,updated);refresh();if(item.quantity>0&&updated==0)alert(item.name);}catch(Exception e){message("Enter a valid quantity");}}).setNegativeButton("Cancel",null).show();}
 private void alert(String item){if(checkSelfPermission(Manifest.permission.SEND_SMS)!=PackageManager.PERMISSION_GRANTED){message("Zero stock: "+item+". SMS disabled.");return;}String phone=getSharedPreferences("sms",0).getString("phone","");if(phone.isEmpty()){message("Set an SMS recipient in notification settings");return;}try{SmsManager.getDefault().sendTextMessage(phone,null,"Inventory alert: "+item+" reached zero stock.",null,null);message("SMS send requested");}catch(Exception e){message("SMS unavailable on this device");}}
}
